const DOCS={"DOC-100": {"area": "security", "level": "standard", "date": "2026-01-15", "text": "# DOC-100 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- MFA\u5f3a\u5236\u8303\u56f4: \u4ec5\u7ba1\u7406\u5458\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n"}, "DOC-101": {"area": "platform", "level": "policy", "date": "2026-02-15", "text": "# DOC-101 (platform)\n\u6587\u6863\u7ea7\u522b: policy\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u65e5\u5fd7\u4fdd\u7559\u5929\u6570: 90\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-102": {"area": "data", "level": "standard", "date": "2026-03-15", "text": "# DOC-102 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-03-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n"}, "DOC-103": {"area": "billing", "level": "standard", "date": "2026-04-15", "text": "# DOC-103 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-04-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n"}, "DOC-104": {"area": "security", "level": "standard", "date": "2026-11-20", "text": "# DOC-104 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-11-20\n## \u89c4\u5b9a\n- \u52a0\u5bc6\u7b97\u6cd5: AES-256-GCM\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-105": {"area": "platform", "level": "standard", "date": "2026-06-15", "text": "# DOC-105 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n"}, "DOC-106": {"area": "data", "level": "standard", "date": "2026-07-15", "text": "# DOC-106 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-07-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n"}, "DOC-107": {"area": "billing", "level": "standard", "date": "2026-02-10", "text": "# DOC-107 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-10\n## \u89c4\u5b9a\n- \u4f1a\u8bdd\u8fc7\u671f\u5206\u949f: 120\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-108": {"area": "security", "level": "standard", "date": "2026-09-15", "text": "# DOC-108 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-09-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n"}, "DOC-109": {"area": "platform", "level": "standard", "date": "2026-01-15", "text": "# DOC-109 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-110": {"area": "data", "level": "standard", "date": "2026-02-15", "text": "# DOC-110 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n"}, "DOC-111": {"area": "billing", "level": "standard", "date": "2026-03-15", "text": "# DOC-111 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-03-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n"}, "DOC-112": {"area": "security", "level": "standard", "date": "2026-04-15", "text": "# DOC-112 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-04-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-113": {"area": "platform", "level": "standard", "date": "2026-05-15", "text": "# DOC-113 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-05-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-114": {"area": "data", "level": "standard", "date": "2026-06-15", "text": "# DOC-114 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n"}, "DOC-115": {"area": "billing", "level": "standard", "date": "2026-02-10", "text": "# DOC-115 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-10\n## \u89c4\u5b9a\n- \u4ee4\u724c\u6709\u6548\u671f\u5929: 30\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n"}, "DOC-116": {"area": "security", "level": "standard", "date": "2026-02-10", "text": "# DOC-116 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-10\n## \u89c4\u5b9a\n- \u5907\u4efd\u9891\u7387\u5c0f\u65f6: 24\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-117": {"area": "platform", "level": "standard", "date": "2026-09-15", "text": "# DOC-117 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-09-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-118": {"area": "data", "level": "standard", "date": "2026-01-15", "text": "# DOC-118 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n"}, "DOC-119": {"area": "billing", "level": "standard", "date": "2026-02-15", "text": "# DOC-119 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n"}, "DOC-120": {"area": "security", "level": "standard", "date": "2026-03-15", "text": "# DOC-120 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-03-15\n## \u89c4\u5b9a\n- \u5bc6\u7801\u6700\u77ed\u957f\u5ea6: 16\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-121": {"area": "platform", "level": "standard", "date": "2026-02-10", "text": "# DOC-121 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-10\n## \u89c4\u5b9a\n- \u52a0\u5bc6\u7b97\u6cd5: ChaCha20-Poly1305\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-122": {"area": "data", "level": "standard", "date": "2026-05-15", "text": "# DOC-122 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-05-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n"}, "DOC-123": {"area": "billing", "level": "standard", "date": "2026-06-15", "text": "# DOC-123 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-124": {"area": "security", "level": "standard", "date": "2026-07-15", "text": "# DOC-124 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-07-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n"}, "DOC-125": {"area": "platform", "level": "standard", "date": "2026-08-15", "text": "# DOC-125 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-08-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-126": {"area": "data", "level": "standard", "date": "2026-09-15", "text": "# DOC-126 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-09-15\n## \u89c4\u5b9a\n- \u65e5\u5fd7\u4fdd\u7559\u5929\u6570: 365\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n"}, "DOC-127": {"area": "billing", "level": "standard", "date": "2026-01-15", "text": "# DOC-127 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n"}, "DOC-128": {"area": "security", "level": "standard", "date": "2026-02-15", "text": "# DOC-128 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n"}, "DOC-129": {"area": "platform", "level": "standard", "date": "2026-03-15", "text": "# DOC-129 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-03-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-130": {"area": "data", "level": "standard", "date": "2026-04-15", "text": "# DOC-130 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-04-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n"}, "DOC-131": {"area": "billing", "level": "standard", "date": "2026-05-15", "text": "# DOC-131 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-05-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-132": {"area": "security", "level": "standard", "date": "2026-06-15", "text": "# DOC-132 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n"}, "DOC-133": {"area": "platform", "level": "standard", "date": "2026-07-15", "text": "# DOC-133 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-07-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-134": {"area": "data", "level": "standard", "date": "2026-08-15", "text": "# DOC-134 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-08-15\n## \u89c4\u5b9a\n- \u9650\u6d41\u9608\u503c\u6bcf\u5206\u949f: 1200\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n"}, "DOC-135": {"area": "billing", "level": "policy", "date": "2026-09-15", "text": "# DOC-135 (billing)\n\u6587\u6863\u7ea7\u522b: policy\n\u751f\u6548\u65e5\u671f: 2026-09-15\n## \u89c4\u5b9a\n- MFA\u5f3a\u5236\u8303\u56f4: \u5168\u5458\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-136": {"area": "security", "level": "standard", "date": "2026-01-15", "text": "# DOC-136 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n"}, "DOC-137": {"area": "platform", "level": "standard", "date": "2026-02-15", "text": "# DOC-137 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n"}, "DOC-138": {"area": "data", "level": "standard", "date": "2026-11-20", "text": "# DOC-138 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-11-20\n## \u89c4\u5b9a\n- \u5907\u4efd\u9891\u7387\u5c0f\u65f6: 6\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n"}, "DOC-139": {"area": "billing", "level": "standard", "date": "2026-04-15", "text": "# DOC-139 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-04-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-140": {"area": "security", "level": "policy", "date": "2026-05-15", "text": "# DOC-140 (security)\n\u6587\u6863\u7ea7\u522b: policy\n\u751f\u6548\u65e5\u671f: 2026-05-15\n## \u89c4\u5b9a\n- \u9650\u6d41\u9608\u503c\u6bcf\u5206\u949f: 600\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-141": {"area": "platform", "level": "standard", "date": "2026-06-15", "text": "# DOC-141 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-142": {"area": "data", "level": "standard", "date": "2026-07-15", "text": "# DOC-142 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-07-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n"}, "DOC-143": {"area": "billing", "level": "standard", "date": "2026-08-15", "text": "# DOC-143 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-08-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n"}, "DOC-144": {"area": "security", "level": "standard", "date": "2026-09-15", "text": "# DOC-144 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-09-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n"}, "DOC-145": {"area": "platform", "level": "standard", "date": "2026-01-15", "text": "# DOC-145 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n"}, "DOC-146": {"area": "data", "level": "standard", "date": "2026-02-15", "text": "# DOC-146 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n"}, "DOC-147": {"area": "billing", "level": "standard", "date": "2026-03-15", "text": "# DOC-147 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-03-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n"}, "DOC-148": {"area": "security", "level": "standard", "date": "2026-04-15", "text": "# DOC-148 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-04-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-149": {"area": "platform", "level": "standard", "date": "2026-11-20", "text": "# DOC-149 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-11-20\n## \u89c4\u5b9a\n- \u4ee4\u724c\u6709\u6548\u671f\u5929: 7\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-150": {"area": "data", "level": "standard", "date": "2026-06-15", "text": "# DOC-150 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n"}, "DOC-151": {"area": "billing", "level": "standard", "date": "2026-07-15", "text": "# DOC-151 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-07-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-152": {"area": "security", "level": "standard", "date": "2026-08-15", "text": "# DOC-152 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-08-15\n## \u89c4\u5b9a\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n"}, "DOC-153": {"area": "platform", "level": "standard", "date": "2026-09-15", "text": "# DOC-153 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-09-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n"}, "DOC-154": {"area": "data", "level": "policy", "date": "2026-01-15", "text": "# DOC-154 (data)\n\u6587\u6863\u7ea7\u522b: policy\n\u751f\u6548\u65e5\u671f: 2026-01-15\n## \u89c4\u5b9a\n- \u5bc6\u7801\u6700\u77ed\u957f\u5ea6: 12\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n"}, "DOC-155": {"area": "billing", "level": "standard", "date": "2026-02-15", "text": "# DOC-155 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-02-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}, "DOC-156": {"area": "security", "level": "standard", "date": "2026-11-20", "text": "# DOC-156 (security)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-11-20\n## \u89c4\u5b9a\n- \u4f1a\u8bdd\u8fc7\u671f\u5206\u949f: 30\n- \u8d85\u65f6\u91cd\u8bd5\u6b21\u6570: 3\n- \u5065\u5eb7\u68c0\u67e5\u95f4\u9694\u79d2: 15\n- \u8fde\u63a5\u6c60\u4e0a\u9650: 200\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u4f9d\u636e\u96c6\u56e2\u4fe1\u606f\u5b89\u5168\u7ba1\u7406\u5236\u5ea6\u5236\u5b9a\uff0c\u9002\u7528\u4e8e\u6240\u6709\u9762\u5411\u516c\u7f51\u63d0\u4f9b\u670d\u52a1\u7684\u751f\u4ea7\u7cfb\u7edf\uff0c\u4ee5\u53ca\u627f\u8f7d\u5ba2\u6237\u4e2a\u4eba\u4fe1\u606f\u7684\u5185\u90e8\u7cfb\u7edf\u3002\u6d4b\u8bd5\u4e0e\u6c99\u7bb1\u73af\u5883\u53ef\u6309\u300c\u4f8b\u5916\u4e0e\u51cf\u514d\u300d\u4e00\u8282\u529e\u7406\u51cf\u514d\uff0c\u4f46\u6d89\u53ca\u771f\u5b9e\u5ba2\u6237\u6570\u636e\u7684\u9664\u5916\u3002\u4e0e\u672c\u89c4\u8303\u51b2\u7a81\u7684\u5386\u53f2\u7ea6\u5b9a\uff0c\u81ea\u672c\u89c4\u8303\u751f\u6548\u65e5\u8d77\u4e0d\u518d\u6267\u884c\u3002\n\n## \u4f8b\u5916\u4e0e\u51cf\u514d\n\n\u786e\u56e0\u6280\u672f\u6761\u4ef6\u9650\u5236\u65e0\u6cd5\u8fbe\u6807\u7684\uff0c\u7531\u7cfb\u7edf\u8d1f\u8d23\u4eba\u63d0\u4ea4\u4f8b\u5916\u7533\u8bf7\uff0c\u6ce8\u660e\u4e0d\u80fd\u8fbe\u6807\u7684\u5177\u4f53\u6761\u6b3e\u3001\u8865\u507f\u63a7\u5236\u63aa\u65bd\u4e0e\u6574\u6539\u671f\u9650\uff0c\u7ecf\u5b89\u5168\u59d4\u5458\u4f1a\u8bc4\u5ba1\u901a\u8fc7\u540e\u65b9\u53ef\u6267\u884c\u3002\u4f8b\u5916\u6709\u6548\u671f\u6700\u957f\u4e0d\u8d85\u8fc7\u4e00\u4e2a\u8003\u6838\u5e74\u5ea6\uff0c\u5230\u671f\u987b\u91cd\u65b0\u7533\u8bf7\uff0c\u4e0d\u5f97\u9ed8\u8ba4\u7eed\u671f\u3002\n\n## \u5ba1\u8ba1\u4e0e\u7559\u75d5\n\n\u5b89\u5168\u76f8\u5173\u4e8b\u4ef6\u5fc5\u987b\u5b8c\u6574\u843d\u5e93\uff0c\u81f3\u5c11\u5305\u542b\u64cd\u4f5c\u4eba\u3001\u65f6\u70b9\u3001\u6765\u6e90\u5730\u5740\u4e0e\u64cd\u4f5c\u5bf9\u8c61\u56db\u9879\u3002\u843d\u5e93\u8303\u56f4\u8986\u76d6\u767b\u5f55\u4e0e\u767b\u5f55\u5931\u8d25\u3001\u6743\u9650\u53d8\u66f4\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u5b89\u5168\u7b56\u7565\u8c03\u6574\u3002\u7559\u75d5\u4e0d\u5f97\u7531\u4e1a\u52a1\u7cfb\u7edf\u81ea\u884c\u5220\u9664\u6216\u6539\u5199\u3002\u5ba1\u8ba1\u62bd\u67e5\u6309\u5b63\u5ea6\u8fdb\u884c\uff0c\u7ed3\u679c\u901a\u62a5\u81f3\u7cfb\u7edf\u8d1f\u8d23\u4eba\u3002\n\n## \u8eab\u4efd\u4e0e\u8bbf\u95ee\n\n\u6240\u6709\u4eba\u5458\u8d26\u53f7\u5fc5\u987b\u4e0e\u4eba\u4e8b\u4e3b\u6570\u636e\u4fdd\u6301\u4e00\u81f4\uff0c\u79bb\u804c\u5f53\u65e5\u51bb\u7ed3\u3001\u4e03\u4e2a\u81ea\u7136\u65e5\u5185\u56de\u6536\u6743\u9650\u3002\u670d\u52a1\u8d26\u53f7\u4e0d\u5f97\u8de8\u7cfb\u7edf\u590d\u7528\uff0c\u4e00\u8d26\u53f7\u4e00\u7528\u9014\uff0c\u7533\u8bf7\u65f6\u987b\u6ce8\u660e\u8c03\u7528\u65b9\u4e0e\u7528\u9014\u3002\u7279\u6743\u64cd\u4f5c\uff08\u751f\u4ea7\u5e93\u76f4\u8fde\u3001\u5bc6\u94a5\u8bfb\u53d6\u3001\u7b56\u7565\u8c03\u6574\uff09\u987b\u53cc\u4eba\u590d\u6838\u5e76\u7559\u75d5\uff0c\u5355\u4eba\u64cd\u4f5c\u89c6\u4e3a\u8fdd\u89c4\u3002\n\n## \u8fdd\u89c4\u5904\u7406\n\n\u62bd\u67e5\u53d1\u73b0\u672a\u6309\u672c\u89c4\u8303\u6267\u884c\u7684\uff0c\u8d23\u4efb\u56e2\u961f\u987b\u5728\u5341\u4e2a\u5de5\u4f5c\u65e5\u5185\u5b8c\u6210\u6574\u6539\u5e76\u63d0\u4ea4\u6574\u6539\u8bf4\u660e\u3002\u540c\u4e00\u95ee\u9898\u8fde\u7eed\u4e24\u6b21\u62bd\u67e5\u672a\u6574\u6539\u7684\uff0c\u6682\u505c\u8be5\u7cfb\u7edf\u7684\u53d8\u66f4\u53d1\u5e03\u6743\u9650\uff0c\u76f4\u81f3\u6574\u6539\u9a8c\u6536\u901a\u8fc7\u3002\n"}, "DOC-157": {"area": "platform", "level": "standard", "date": "2026-04-15", "text": "# DOC-157 (platform)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-04-15\n## \u89c4\u5b9a\n- \u5ba1\u8ba1\u91c7\u6837\u7387: 0.1\n- \u961f\u5217\u6700\u5927\u957f\u5ea6: 5000\n- \u8bc1\u4e66\u8f6e\u6362\u5929\u6570: 180\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n"}, "DOC-158": {"area": "data", "level": "standard", "date": "2026-05-15", "text": "# DOC-158 (data)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-05-15\n## \u89c4\u5b9a\n- \u6162\u67e5\u8be2\u9608\u503c\u6beb\u79d2: 800\n- \u5e76\u53d1\u4e0a\u4f20\u6570: 4\n- \u7f13\u5b58\u8fc7\u671f\u79d2: 600\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u6570\u636e\u7684\u5206\u7ea7\u3001\u5b58\u50a8\u3001\u5907\u4efd\u4e0e\u9500\u6bc1\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u7ed3\u6784\u5316\u4e0e\u975e\u7ed3\u6784\u5316\u6570\u636e\uff0c\u8986\u76d6\u751f\u4ea7\u5e93\u3001\u6570\u636e\u4ed3\u5e93\u3001\u5bf9\u8c61\u5b58\u50a8\u4ee5\u53ca\u5404\u7c7b\u79bb\u7ebf\u5bfc\u51fa\u6587\u4ef6\u3002\n\n## \u6570\u636e\u9500\u6bc1\n\n\u5230\u671f\u6570\u636e\u6309\u9500\u6bc1\u6d41\u7a0b\u5904\u7406\uff0c\u9500\u6bc1\u524d\u987b\u786e\u8ba4\u65e0\u672a\u7ed3\u7684\u5ba1\u8ba1\u8981\u6c42\u4e0e\u6cd5\u52a1\u4fdd\u5168\u901a\u77e5\u3002\u7269\u7406\u4ecb\u8d28\u9500\u6bc1\u987b\u53cc\u4eba\u5728\u573a\u5e76\u7559\u5b58\u5f71\u50cf\u8bb0\u5f55\uff0c\u9500\u6bc1\u6e05\u5355\u5f52\u6863\u4fdd\u5b58\u4e09\u5e74\u3002\n\n## \u8de8\u5883\u4f20\u8f93\n\n\u6d89\u53ca\u8de8\u5883\u7684\u6570\u636e\u4f20\u8f93\u987b\u5b8c\u6210\u5b89\u5168\u8bc4\u4f30\u4e0e\u5408\u89c4\u5907\u6848\uff0c\u8bc4\u4f30\u7ed3\u8bba\u6709\u6548\u671f\u4e00\u5e74\uff0c\u8d85\u671f\u987b\u91cd\u65b0\u8bc4\u4f30\u3002\u8bc4\u4f30\u672a\u901a\u8fc7\u524d\u4e0d\u5f97\u5f00\u901a\u4f20\u8f93\u94fe\u8def\u3002\n\n## \u5206\u7ea7\u4e0e\u6807\u8bc6\n\n\u6570\u636e\u6309\u516c\u5f00\u3001\u5185\u90e8\u3001\u654f\u611f\u3001\u673a\u5bc6\u56db\u7ea7\u7ba1\u7406\uff0c\u7531\u6570\u636e\u6240\u6709\u8005\u8ba4\u5b9a\u5e76\u767b\u8bb0\u3002\u654f\u611f\u53ca\u4ee5\u4e0a\u6570\u636e\u843d\u76d8\u5fc5\u987b\u52a0\u5bc6\uff1b\u5bfc\u51fa\u987b\u8d70\u5ba1\u6279\u5e76\u751f\u6210\u6c34\u5370\uff0c\u7981\u6b62\u5bfc\u51fa\u5230\u4e2a\u4eba\u7ec8\u7aef\u6216\u4e2a\u4eba\u4e91\u76d8\u3002\n\n## \u5907\u4efd\u4e0e\u6062\u590d\n\n\u5907\u4efd\u6709\u6548\u6027\u987b\u6309\u5b63\u5ea6\u505a\u6062\u590d\u6f14\u7ec3\uff0c\u6f14\u7ec3\u8986\u76d6\u5168\u91cf\u4e0e\u589e\u91cf\u4e24\u6761\u8def\u5f84\uff0c\u7ed3\u679c\u8bb0\u5165\u8fd0\u7ef4\u53f0\u8d26\u3002\u6f14\u7ec3\u5931\u8d25\u7684\u987b\u5728\u4e24\u5468\u5185\u5b9a\u4f4d\u5e76\u590d\u6d4b\uff0c\u590d\u6d4b\u901a\u8fc7\u524d\u4e0d\u5f97\u5173\u95ed\u5de5\u5355\u3002\n"}, "DOC-159": {"area": "billing", "level": "standard", "date": "2026-06-15", "text": "# DOC-159 (billing)\n\u6587\u6863\u7ea7\u522b: standard\n\u751f\u6548\u65e5\u671f: 2026-06-15\n## \u89c4\u5b9a\n- \u5206\u7247\u5927\u5c0fMB: 64\n- \u5fc3\u8df3\u8d85\u65f6\u79d2: 45\n- \u6279\u91cf\u63d0\u4ea4\u6761\u6570: 500\n\n## \u9002\u7528\u8303\u56f4\n\n\u672c\u89c4\u8303\u89c4\u5b9a\u751f\u4ea7\u7cfb\u7edf\u7684\u53d8\u66f4\u3001\u53d1\u5e03\u3001\u76d1\u63a7\u4e0e\u503c\u73ed\u8981\u6c42\uff0c\u9002\u7528\u4e8e\u6240\u6709\u627f\u8f7d\u5bf9\u5916\u4e1a\u52a1\u7684\u5e94\u7528\u4e0e\u4e2d\u95f4\u4ef6\uff0c\u542b\u5176\u4f9d\u8d56\u7684\u6570\u636e\u5e93\u4e0e\u7f13\u5b58\u7ec4\u4ef6\u3002\n\n## \u53d8\u66f4\u7ba1\u7406\n\n\u53d8\u66f4\u5206\u5e38\u89c4\u3001\u7d27\u6025\u3001\u91cd\u5927\u4e09\u7c7b\uff0c\u5bf9\u5e94\u4e0d\u540c\u7684\u5ba1\u6279\u5c42\u7ea7\u4e0e\u6267\u884c\u7a97\u53e3\u3002\u6240\u6709\u53d8\u66f4\u987b\u6709\u56de\u6eda\u65b9\u6848\uff0c\u56de\u6eda\u65b9\u6848\u672a\u7ecf\u9a8c\u8bc1\u7684\u4e0d\u4e88\u653e\u884c\u3002\u91cd\u5927\u53d8\u66f4\u987b\u505a\u7070\u5ea6\uff0c\u7070\u5ea6\u671f\u95f4\u4fdd\u7559\u4e00\u952e\u56de\u9000\u80fd\u529b\u3002\n\n## \u5bb9\u91cf\u7ba1\u7406\n\n\u6309\u6708\u8bc4\u4f30\u5bb9\u91cf\u6c34\u4f4d\u3002\u6c34\u4f4d\u6301\u7eed\u8d85\u8fc7\u4e03\u6210\u7684\u987b\u63d0\u4ea4\u6269\u5bb9\u8ba1\u5212\uff0c\u8d85\u8fc7\u4e5d\u6210\u7684\u6309\u7d27\u6025\u53d8\u66f4\u5904\u7406\u3002\n\n## \u503c\u73ed\u4e0e\u4ea4\u63a5\n\n\u503c\u73ed\u4ee5\u73ed\u4e3a\u5355\u4f4d\u4ea4\u63a5\uff0c\u4ea4\u63a5\u5185\u5bb9\u5305\u542b\u5728\u9014\u53d8\u66f4\u3001\u672a\u95ed\u73af\u544a\u8b66\u4e0e\u5df2\u77e5\u98ce\u9669\u4e09\u9879\uff0c\u4ea4\u63a5\u8bb0\u5f55\u987b\u53cc\u65b9\u786e\u8ba4\u3002\u503c\u73ed\u671f\u95f4\u53d1\u751f P1 \u6545\u969c\u7684\u987b\u5728\u56db\u5341\u516b\u5c0f\u65f6\u5185\u4ea7\u51fa\u590d\u76d8\u3002\n\n## \u76d1\u63a7\u4e0e\u544a\u8b66\n\n\u6838\u5fc3\u6307\u6807\u5fc5\u987b\u914d\u7f6e\u544a\u8b66\uff0c\u6bcf\u6761\u544a\u8b66\u987b\u6709\u660e\u786e\u8d23\u4efb\u4eba\u4e0e\u5904\u7f6e\u624b\u518c\u3002\u8fde\u7eed\u8bef\u62a5\u7684\u544a\u8b66\u987b\u5728\u4e24\u5468\u5185\u8c03\u4f18\u6216\u4e0b\u7ebf\uff0c\u957f\u671f\u9759\u9ed8\u7684\u544a\u8b66\u89c6\u4e3a\u65e0\u6548\u544a\u8b66\u3002\n"}};      // id -> {area,level,date,text}
export default { id:"hb-specaudit", name:"hb-specaudit", description:"cross-document spec audit",
  register(api){
    api.registerTool({name:"spec_list",description:"List all specification documents by area.",
      parameters:{type:"object",properties:{area:{type:"string"}},additionalProperties:false},
      async execute(id,a){const ar=a&&a.area?String(a.area):"";
        const ks=Object.keys(DOCS).filter(k=>!ar||DOCS[k].area===ar);
        return T("DOCS "+ks.map(k=>k+"("+DOCS[k].area+")").join(", "));}});
    api.registerTool({name:"spec_read",description:"Read one specification document in full.",
      parameters:{type:"object",properties:{doc:{type:"string"}},required:["doc"],additionalProperties:false},
      async execute(id,a){const d=DOCS[String(a.doc||"")]; if(!d)return T("NO_SUCH_DOC");
        return T(d.text);}});
  }};
